function update(dt){elapsed+=dt;timeLeft=Math.max(0,timeLeft-dt);pulseCooldown=Math.max(0,pulseCooldown-dt);bridgeTimer=Math.max(0,bridgeTimer-dt);bridge.visible=bridgeTimer>0;if(invulnerable>0)invulnerable-=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}if(timeLeft<=0){finish(false,'Nightfall has settled over the northwood. The lantern seeds have gone dim.');return}
  // responsive movement in the plane of the forest
  let dx=(input.right?1:0)-(input.left?1:0),dz=(input.down?1:0)-(input.up?1:0);const len=Math.hypot(dx,dz);if(len){dx/=len;dz/=len;const speed=input.run?6.1:4.15,old=player.position.clone(),nx=old.x+dx*speed*dt,nz=old.z+dz*speed*dt;let blocked=false;
    if(Math.abs(nx)>33||Math.abs(nz)>34)blocked=true;
    if(!blocked&&Math.abs(nz)<3.15&&Math.abs(old.z)>=3.15&&(!bridgeTimer||Math.abs(nx)>1.02))blocked=true;
    if(!blocked&&Math.abs(nz)<3.15&&Math.abs(nx)>1.02)blocked=true;
    if(!blocked){for(const t of trees){const ox=nx-t.x,oz=nz-t.z;if(ox*ox+oz*oz<(t.r+.48)**2){blocked=true;break}}}
    if(!blocked){player.position.x=nx;player.position.z=nz;player.rotation.y=Math.atan2(dx,-dz);}
  }
  body.position.y=.82+(len?Math.abs(Math.sin(elapsed*13))*.055:Math.sin(elapsed*2)*.018);hood.position.y=1.72+(len?Math.abs(Math.sin(elapsed*13))*.055:0);
  for(const s of seeds){if(s.got)continue;s.group.rotation.y+=dt*.85;s.group.position.y=s.baseY+Math.sin(elapsed*2.1+s.group.position.x)*.14;if(player.position.distanceTo(s.group.position)<1.45){s.got=true;s.group.visible=false;collected++;toast(collected===3?'ALL THREE SEEDS — WAKE THE SHRINE':'A LANTERN SEED REMEMBERS');updateHud()}}
  for(const gh of ghosts){gh.phase+=dt;gh.group.position.y=1.05+Math.sin(gh.phase*2.2)*.22;if(gh.stun>0){gh.stun-=dt;gh.group.rotation.z=Math.sin(gh.phase*7)*.13;continue}const dxp=player.position.x-gh.group.position.x,dzp=player.position.z-gh.group.position.z,d=Math.hypot(dxp,dzp);if(d>1.1){const speed=1.9+(gh.phase%1)*.16;gh.group.position.x+=dxp/d*speed*dt;gh.group.position.z+=dzp/d*speed*dt;gh.group.rotation.y=Math.atan2(dxp,-dzp)}if(d<1.17&&invulnerable<=0){health--;invulnerable=1.65;player.position.x-=dxp/Math.max(d,.01)*1.6;player.position.z-=dzp/Math.max(d,.01)*1.6;toast(health?'A MURMUR TOOK A HEART':'THE DARK FOUND YOU');updateHud();if(health<=0){finish(false,'The murmurs closed in before you could bring the lantern seeds home.');return}}}
  for(const wave of pulseWaves){wave.age+=dt;const scale=1+wave.age*8;wave.mesh.scale.setScalar(scale);wave.mesh.material.opacity=Math.max(0,.88-wave.age*.55);if(wave.age>1.6){scene.remove(wave.mesh);wave.mesh.geometry.dispose();wave.mesh.material.dispose()}}pulseWaves=pulseWaves.filter(w=>w.age<=1.6);
  flies.children.forEach(f=>{f.position.x=f.userData.base.x+Math.sin(elapsed*.7+f.userData.phase)*.45;f.position.y=f.userData.base.y+Math.sin(elapsed*1.6+f.userData.phase)*.42;f.position.z=f.userData.base.z+Math.cos(elapsed*.55+f.userData.phase)*.4});
  shrine.rotation.y+=dt*.35;shrine.position.y=2.05+Math.sin(elapsed*1.5)*.11;
  if(collected===3&&player.position.distanceTo(new THREE.Vector3(0,0,-30))<2.8){finish(true);return}
  // soft follow camera and a little spring in the lantern's gaze
  const desired=new THREE.Vector3(player.position.x,player.position.y+10.5,player.position.z+13.5);camera.position.lerp(desired,1-Math.exp(-dt*3.4));camera.lookAt(player.position.x,player.position.y+.7,player.position.z-1.6);
  updateHud();
}
function render(){requestAnimationFrame(render);const dt=Math.min(clock.getDelta(),.045);if(playing)update(dt);else{const t=clock.elapsedTime;camera.position.x=Math.sin(t*.09)*.8;camera.position.y=10.5;camera.position.z=43;camera.lookAt(0,0,20);shrine.rotation.y+=dt*.25;seeds.forEach((s,i)=>{if(!s.got){s.group.rotation.y+=dt*.3;s.group.position.y=s.baseY+Math.sin(t*1.6+i)*.12}});flies.children.forEach(f=>{f.position.y=f.userData.base.y+Math.sin(t+f.userData.phase)*.3})}renderer.render(scene,camera)}render();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});
</script></body></html>

